from itertools import groupby

def longest_positive_run_sum(lst):
    best_len = 0
    best_sum = 0
    for is_pos, group in groupby(lst, key=lambda x: x > 0):
        if is_pos:
            run = list(group)
            if len(run) > best_len:
                best_len = len(run)
                best_sum = sum(run)
    return best_sum

